INSERT INTO `news` (`ID`, `title`, `description`, `date`) VALUES
(2, 'BETA-runde før 18. Januar', 'Ettersom vi ønsker minst mulig feil før åpning 18. Januar så kjører vi en BETA runde frem til 17. Januar.\r\nDet blir full RS den 17. Januar slik at alle begynner på blanke ark på åpningsdagen 18. Januar. Om dere finner feil ved spillet så registrer de til meg på discord: [url=https://discord.gg/YD9Pxyu]https://discord.gg/YD9Pxyu[/url]\r\n\r\nHappy ranking <3\r\nMvh Skitzo', 1578235744);
